// Des: Cloud SQL interface, dialects, safe literals, upserts, network client
// Flo: escape text per dialect > build upsert per dialect > Net client sends statements through the vendor adapter > errors are typed
// I/O: statements as text (sync, purge) > rows written in the cloud DB (Turso, Neon, TiDB)
// ===================================================================
const std = @import("std"); const base = @import("nt-vend-base.zig"); const cfgz = @import("cf-conf-load.zig"); const turs = @import("sy-clou-turs.zig"); const neon = @import("sy-clou-neon.zig"); const tidb = @import("sy-clou-tidb.zig");
pub const Dial = enum { sqlt, pgsq, mysq };
pub const Kind = enum { turs, neon, tidb };
pub const Sqlz = struct { ctx2: *anyopaque, dial: Dial, exec: *const fn (ctx2: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, stm2: []const []const u8) anyerror!void };
pub const Colz = struct { name: []const u8, valu: []const u8 };
pub const DDL = [_][]const u8{ "CREATE TABLE IF NOT EXISTS cl_page(urlh CHAR(64) PRIMARY KEY, urlz TEXT, hexz CHAR(64), code INT, tier INT, vend VARCHAR(8), fetc BIGINT)", "CREATE TABLE IF NOT EXISTS cl_reco(urlh CHAR(64) PRIMARY KEY, hexz CHAR(64), kind VARCHAR(8), body TEXT, timz BIGINT)", "CREATE TABLE IF NOT EXISTS cl_manif(hexz CHAR(64) PRIMARY KEY, pack VARCHAR(200), offs BIGINT, lenz BIGINT)", "CREATE TABLE IF NOT EXISTS cl_purg(packz VARCHAR(200) PRIMARY KEY, timz BIGINT, ents INT)" };
pub fn dialOfzz(kind: Kind) Dial { return switch (kind) { .turs => .sqlt, .neon => .pgsq, .tidb => .mysq }; }
pub fn litz(aren: std.mem.Allocator, dial: Dial, text: []const u8) ![]u8 { var outp: std.ArrayList(u8) = .empty; try outp.append(aren, '\''); for (text) |byte| { if (byte == 0) return error.BadText; if (byte == '\'') { try outp.appendSlice(aren, "''"); } else if (byte == '\\' and dial == .mysq) { try outp.appendSlice(aren, "\\\\"); } else { try outp.append(aren, byte); } } try outp.append(aren, '\''); return outp.toOwnedSlice(aren); }
pub fn upse(aren: std.mem.Allocator, dial: Dial, tab2: []const u8, key2: []const u8, cols: []const Colz) ![]u8 { var nam3: std.ArrayList(u8) = .empty; var vals: std.ArrayList(u8) = .empty; var upds: std.ArrayList(u8) = .empty; for (cols, 0..) |colz, ind3| { if (ind3 > 0) { try nam3.appendSlice(aren, ","); try vals.appendSlice(aren, ","); } try nam3.appendSlice(aren, colz.name); try vals.appendSlice(aren, colz.valu); if (std.mem.eql(u8, colz.name, key2)) continue; if (upds.items.len > 0) try upds.appendSlice(aren, ","); if (dial == .mysq) try upds.print(aren, "{s}=VALUES({s})", .{ colz.name, colz.name }) else try upds.print(aren, "{s}=excluded.{s}", .{ colz.name, colz.name }); } if (dial == .mysq) return std.fmt.allocPrint(aren, "INSERT INTO {s}({s}) VALUES({s}) ON DUPLICATE KEY UPDATE {s}", .{ tab2, nam3.items, vals.items, upds.items }); return std.fmt.allocPrint(aren, "INSERT INTO {s}({s}) VALUES({s}) ON CONFLICT({s}) DO UPDATE SET {s}", .{ tab2, nam3.items, vals.items, key2, upds.items }); }
pub const Netz = struct { kind: Kind, end2: cfgz.Endp, key2: []const u8, send: base.Send, gpaz: std.mem.Allocator,
pub fn sql2(self: *Netz) Sqlz { return .{ .ctx2 = self, .dial = dialOfzz(self.kind), .exec = exe3 }; }
fn exe3(ctx2: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, stm2: []const []const u8) anyerror!void { const self: *Netz = @ptrCast(@alignCast(ctx2)); if (stm2.len == 0) return; switch (self.kind) { .turs => { const back = try self.send.call(self.send.ctx2, self.gpaz, iozz, try turs.requBuil(aren, self.end2, self.key2, stm2)); defer self.gpaz.free(back.body); try turs.respChek(aren, back); }, .neon => for (stm2) |stmz| { const back = try self.send.call(self.send.ctx2, self.gpaz, iozz, try neon.requBuil(aren, self.end2, self.key2, stmz)); defer self.gpaz.free(back.body); try neon.respChek(back); }, .tidb => for (stm2) |stmz| { const back = try self.send.call(self.send.ctx2, self.gpaz, iozz, try tidb.requBuil(aren, self.end2, self.key2, stmz)); defer self.gpaz.free(back.body); try tidb.respChek(back); } } } };
